const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries and time period
  const point1 = ee.Geometry.Point([-79.198692, 43.244129]);
  const point2 = ee.Geometry.Point([-79.069485, 43.263113]);
  const date = '2021-02-04';
  const dateStart = ee.Date(date).advance(-3, 'day');
  const dateEnd = ee.Date(date).advance(3, 'day');

  // 2. Load Sentinel-2 collection
  let collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterDate(dateStart, dateEnd)
    .filterBounds(point1.union(point2));

  let collectionSize = await collection.size().getInfo();
  console.log(`Sentinel-2 images found: ${collectionSize}`);

  // Fallback to Landsat 8 if no Sentinel-2
  if (collectionSize === 0) {
    console.log('Trying Landsat 8...');
    collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterDate(dateStart, dateEnd)
      .filterBounds(point1.union(point2));
    collectionSize = await collection.size().getInfo();
    console.log(`Landsat 8 images found: ${collectionSize}`);

    if (collectionSize === 0) {
      console.log('No images found for either location in date range.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Process based on collection type
  let ndviImage;
  if (collection.first().bandNames().contains('B8').getInfo()) {
    // Sentinel-2 processing
    const maskClouds = function(image) {
      const qa = image.select('QA60');
      const cloudMask = qa.bitwiseAnd(1 << 10).eq(0)
        .and(qa.bitwiseAnd(1 << 11).eq(0));
      return image.updateMask(cloudMask);
    };

    const addNDVI = function(image) {
      const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
      return image.addBands(ndvi);
    };

    ndviImage = collection.map(maskClouds).map(addNDVI).select('NDVI').median();
  } else {
    // Landsat 8 processing
    const maskClouds = function(image) {
      const qa = image.select('QA_PIXEL');
      const cloudMask = qa.bitwiseAnd(1 << 3).eq(0)
        .and(qa.bitwiseAnd(1 << 4).eq(0));
      return image.updateMask(cloudMask);
    };

    const addNDVI = function(image) {
      const ndvi = image.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
      return image.addBands(ndvi);
    };

    ndviImage = collection.map(maskClouds).map(addNDVI).select('NDVI').median();
  }

  // 4. Calculate NDVI and pixel counts for both locations
  const buffer = 500; // 500m buffer around each point
  const region1 = point1.buffer(buffer);
  const region2 = point2.buffer(buffer);

  const stats1 = await ndviImage.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: region1,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = await ndviImage.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: region2,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const ndvi1 = stats1.NDVI_mean;
  const count1 = stats1.NDVI_count;
  const ndvi2 = stats2.NDVI_mean;
  const count2 = stats2.NDVI_count;

  console.log(`Point 1 (-79.198692, 43.244129): NDVI=${ndvi1 !== null ? ndvi1.toFixed(4) : 'null'}, Pixels=${count1}`);
  console.log(`Point 2 (-79.069485, 43.263113): NDVI=${ndvi2 !== null ? ndvi2.toFixed(4) : 'null'}, Pixels=${count2}`);

  // 5. Validation and final answer
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2) || ndvi1 < -1 || ndvi1 > 1 || ndvi2 < -1 || ndvi2 > 1) {
    console.log('Invalid NDVI values detected.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (ndvi1 > ndvi2) {
    console.log('Point 1 is greener than Point 2.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Point 1 is not greener than Point 2.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
